using CrestApps.OrchardCore.ContactCenter.Core;
using CrestApps.OrchardCore.ContactCenter.Reports.Models;
using CrestApps.OrchardCore.ContactCenter.Reports.Providers;
using CrestApps.OrchardCore.Reports;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Options;
using OrchardCore.Localization;

namespace CrestApps.OrchardCore.ContactCenter.Reports.Services;

/// <summary>
/// Adds the Contact Center report catalog to <see cref="ReportOptions"/>: a descriptor per enterprise interaction and
/// agent workforce report. One class runs every report of a family, so a report is created with its kind only when it
/// is run, and another feature can add or remove catalog reports through the same options.
/// </summary>
internal sealed class ConfigureContactCenterReportCatalog : IConfigureOptions<ReportOptions>
{
    private static readonly ObjectFactory<EnterpriseInteractionReportProvider> _enterpriseFactory =
        ActivatorUtilities.CreateFactory<EnterpriseInteractionReportProvider>([typeof(EnterpriseInteractionReportKind)]);

    private static readonly ObjectFactory<AgentWorkforceReportProvider> _workforceFactory =
        ActivatorUtilities.CreateFactory<AgentWorkforceReportProvider>([typeof(AgentWorkforceReportKind)]);

    /// <inheritdoc/>
    public void Configure(ReportOptions options)
    {
        void AddEnterprise(string name, LocalizationSource displayName, LocalizationSource description, EnterpriseInteractionReportKind kind, string category)
        {
            options.Add(new ReportDescriptor(
                name,
                displayName,
                description,
                category,
                ContactCenterPermissions.ViewReports,
                typeof(EnterpriseInteractionReportProvider),
                services => _enterpriseFactory(services, [kind])));
        }

        void AddWorkforce(string name, LocalizationSource displayName, LocalizationSource description, AgentWorkforceReportKind kind, string category)
        {
            options.Add(new ReportDescriptor(
                name,
                displayName,
                description,
                category,
                ContactCenterPermissions.ViewReports,
                typeof(AgentWorkforceReportProvider),
                services => _workforceFactory(services, [kind])));
        }

        AddEnterprise("contact-center-executive-performance", LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Executive performance dashboard"), LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Enterprise KPI cards and interactive charts for interaction demand, accessibility, channel mix, queue service level, agent workload, and operating efficiency."), EnterpriseInteractionReportKind.ExecutiveSummary, ReportsConstants.Categories.Executive);
        AddEnterprise("contact-center-interaction-volume-trend", LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Interaction volume trend"), LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Daily offered, answered, abandoned, and failed interaction volume."), EnterpriseInteractionReportKind.VolumeTrend, ReportsConstants.Categories.Operations);
        AddEnterprise("contact-center-interval-performance", LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Interval performance"), LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Daily interaction outcomes, answer and abandonment rates, speed of answer, and handle time."), EnterpriseInteractionReportKind.IntervalPerformance, ReportsConstants.Categories.Operations);
        AddEnterprise("contact-center-channel-performance", LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Channel performance"), LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Interaction performance grouped by voice, chat, email, SMS, and other supported channels."), EnterpriseInteractionReportKind.ChannelPerformance, ReportsConstants.Categories.Operations);
        AddEnterprise("contact-center-direction-performance", LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Direction performance"), LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Inbound and outbound interaction performance with consistent outcome and duration metrics."), EnterpriseInteractionReportKind.DirectionPerformance, ReportsConstants.Categories.Operations);
        AddEnterprise("contact-center-provider-performance", LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Provider performance"), LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Interaction outcomes and duration metrics grouped by executing communications provider."), EnterpriseInteractionReportKind.ProviderPerformance, ReportsConstants.Categories.Technical);
        AddEnterprise("contact-center-outcome-performance", LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Interaction outcome summary"), LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Interaction volume and response metrics grouped by normalized lifecycle outcome."), EnterpriseInteractionReportKind.OutcomePerformance, ReportsConstants.Categories.Operations);
        AddEnterprise("contact-center-interaction-detail", LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Interaction detail"), LocalizationSource.Create<ConfigureContactCenterReportCatalog>("One row per interaction with routing, agent, provider, timing, and transfer details."), EnterpriseInteractionReportKind.InteractionDetail, ReportsConstants.Categories.ComplianceAudit);
        AddEnterprise("contact-center-transfer-analysis", LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Transfer analysis"), LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Transfer volume, completion, destination type, result, and completion time."), EnterpriseInteractionReportKind.TransferAnalysis, ReportsConstants.Categories.QueueRouting);
        AddEnterprise("contact-center-recording-coverage", LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Recording coverage"), LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Answered voice interaction recording coverage grouped by provider."), EnterpriseInteractionReportKind.RecordingCoverage, ReportsConstants.Categories.ComplianceAudit);
        AddEnterprise("contact-center-queue-service-level", LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Queue service level"), LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Queue service level calculated from answered-within-threshold interactions and eligible offered interactions."), EnterpriseInteractionReportKind.QueueServiceLevel, ReportsConstants.Categories.QueueRouting);
        AddEnterprise("contact-center-queue-abandonment", LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Queue abandonment analysis"), LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Inbound queue offered, answered, abandoned, abandonment rate, and wait before abandonment."), EnterpriseInteractionReportKind.QueueAbandonment, ReportsConstants.Categories.QueueRouting);
        AddEnterprise("contact-center-agent-handle-time", LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Agent handle time analysis"), LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Per-agent handled volume, connected time, wrap-up time, and total handle time."), EnterpriseInteractionReportKind.AgentHandleTime, ReportsConstants.Categories.AgentPerformance);
        AddEnterprise("contact-center-wrap-up-performance", LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Agent wrap-up performance"), LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Per-agent wrap-up starts, completions, completion rate, average duration, and total duration."), EnterpriseInteractionReportKind.WrapUpPerformance, ReportsConstants.Categories.AgentPerformance);
        AddEnterprise("contact-center-hour-of-day-performance", LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Hour-of-day performance"), LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Interaction demand, outcomes, and response metrics grouped by UTC hour."), EnterpriseInteractionReportKind.HourOfDayPerformance, ReportsConstants.Categories.Operations);
        AddEnterprise("contact-center-day-of-week-performance", LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Day-of-week performance"), LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Interaction demand, outcomes, and response metrics grouped by weekday."), EnterpriseInteractionReportKind.DayOfWeekPerformance, ReportsConstants.Categories.Operations);
        AddEnterprise("contact-center-queue-performance", LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Queue performance summary"), LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Interaction volume, outcomes, answer rate, abandonment, ASA, and AHT by queue."), EnterpriseInteractionReportKind.QueuePerformance, ReportsConstants.Categories.QueueRouting);
        AddEnterprise("contact-center-queue-wait-time", LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Queue wait time analysis"), LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Total, average, and maximum customer wait time by queue."), EnterpriseInteractionReportKind.QueueWaitTime, ReportsConstants.Categories.QueueRouting);
        AddEnterprise("contact-center-queue-handle-time", LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Queue handle time analysis"), LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Total, average, and maximum connected plus wrap-up time by queue."), EnterpriseInteractionReportKind.QueueHandleTime, ReportsConstants.Categories.QueueRouting);
        AddEnterprise("contact-center-queue-transfer-performance", LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Queue transfer performance"), LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Handled interactions, transferred interactions, transfer events, and transfer rate by queue."), EnterpriseInteractionReportKind.QueueTransferPerformance, ReportsConstants.Categories.QueueRouting);
        AddEnterprise("contact-center-agent-volume", LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Agent interaction volume"), LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Handled, answered, failed, transferred, recorded, and average handle time by agent."), EnterpriseInteractionReportKind.AgentVolume, ReportsConstants.Categories.AgentPerformance);
        AddEnterprise("contact-center-agent-outcomes", LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Agent outcome performance"), LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Interaction outcomes and average handle time by agent, ordered by failed volume."), EnterpriseInteractionReportKind.AgentOutcome, ReportsConstants.Categories.AgentPerformance);
        AddEnterprise("contact-center-agent-inbound", LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Agent inbound performance"), LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Inbound handled volume, outcomes, transfers, recording count, and handle time by agent."), EnterpriseInteractionReportKind.AgentInbound, ReportsConstants.Categories.AgentPerformance);
        AddEnterprise("contact-center-agent-outbound", LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Agent outbound performance"), LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Outbound handled volume, outcomes, transfers, recording count, and handle time by agent."), EnterpriseInteractionReportKind.AgentOutbound, ReportsConstants.Categories.AgentPerformance);
        AddEnterprise("contact-center-agent-transfers", LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Agent transfer performance"), LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Transfer volume and supporting interaction metrics by agent."), EnterpriseInteractionReportKind.AgentTransferPerformance, ReportsConstants.Categories.AgentPerformance);
        AddEnterprise("contact-center-agent-recording-coverage", LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Agent recording coverage"), LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Recorded interaction volume and supporting performance metrics by agent."), EnterpriseInteractionReportKind.AgentRecordingCoverage, ReportsConstants.Categories.ComplianceAudit);
        AddEnterprise("contact-center-queue-usage-billing", LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Queue usage for billing"), LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Interaction counts, connected time, wrap-up, queue wait, transfers, and recordings by queue for invoice support."), EnterpriseInteractionReportKind.QueueUsageBilling, ReportsConstants.Categories.BillingUsage);
        AddEnterprise("contact-center-agent-usage-billing", LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Agent usage for billing"), LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Interaction counts and measured service time by agent for staffing, payroll, and chargeback support."), EnterpriseInteractionReportKind.AgentUsageBilling, ReportsConstants.Categories.BillingUsage);
        AddEnterprise("contact-center-provider-usage-billing", LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Provider usage for billing"), LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Interaction counts and measured service time by communications provider for vendor invoice reconciliation."), EnterpriseInteractionReportKind.ProviderUsageBilling, ReportsConstants.Categories.BillingUsage);
        AddEnterprise("contact-center-channel-usage-billing", LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Channel usage for billing"), LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Interaction counts and measured service time by channel for service allocation and chargeback."), EnterpriseInteractionReportKind.ChannelUsageBilling, ReportsConstants.Categories.BillingUsage);
        AddEnterprise("contact-center-daily-usage-billing", LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Daily usage for billing"), LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Daily interaction counts and measured service time for invoice period reconciliation."), EnterpriseInteractionReportKind.DailyUsageBilling, ReportsConstants.Categories.BillingUsage);
        AddEnterprise("contact-center-long-interactions", LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Long interaction detail"), LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Interaction-level audit of connected sessions lasting at least 15 minutes."), EnterpriseInteractionReportKind.LongInteractionDetail, ReportsConstants.Categories.ComplianceAudit);
        AddEnterprise("contact-center-failed-interactions", LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Failed interaction detail"), LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Interaction-level audit of failed communications."), EnterpriseInteractionReportKind.FailedInteractionDetail, ReportsConstants.Categories.Technical);
        AddEnterprise("contact-center-abandoned-interactions", LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Abandoned interaction detail"), LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Interaction-level audit of inbound customers who left before answer."), EnterpriseInteractionReportKind.AbandonedInteractionDetail, ReportsConstants.Categories.ComplianceAudit);
        AddEnterprise("contact-center-high-wait-interactions", LocalizationSource.Create<ConfigureContactCenterReportCatalog>("High-wait interaction detail"), LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Interaction-level audit of customers who waited at least 60 seconds."), EnterpriseInteractionReportKind.HighWaitDetail, ReportsConstants.Categories.QueueRouting);
        AddEnterprise("contact-center-lifecycle-duration", LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Interaction lifecycle duration"), LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Average wait, connected, wrap-up, and end-to-end duration by interaction status."), EnterpriseInteractionReportKind.LifecycleDuration, ReportsConstants.Categories.Operations);
        AddEnterprise("contact-center-call-leg-performance", LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Call leg performance"), LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Provider call-leg volume, answer state, status, and average duration for technical operations."), EnterpriseInteractionReportKind.CallLegPerformance, ReportsConstants.Categories.Technical);

        AddWorkforce("contact-center-agent-time-summary", LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Agent time summary"), LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Observed signed-in, available, busy, wrap-up, break, and other not-ready time by agent."), AgentWorkforceReportKind.TimeSummary, ReportsConstants.Categories.WorkforcePayroll);
        AddWorkforce("contact-center-agent-daily-timecard", LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Daily agent timecard"), LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Daily observed on-duty, productive presence, working, and break time by agent."), AgentWorkforceReportKind.DailyTimecard, ReportsConstants.Categories.WorkforcePayroll);
        AddWorkforce("contact-center-presence-status-duration", LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Presence status duration"), LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Total observed duration and share of signed-in time for every presence status."), AgentWorkforceReportKind.StatusDuration, ReportsConstants.Categories.WorkforcePayroll);
        AddWorkforce("contact-center-agent-break-analysis", LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Agent break and away analysis"), LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Break count, total time, average duration, and longest duration by agent."), AgentWorkforceReportKind.BreakAnalysis, ReportsConstants.Categories.WorkforcePayroll);
        AddWorkforce("contact-center-ready-not-ready", LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Ready versus not-ready time"), LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Ready, actively working, and not-ready time by agent."), AgentWorkforceReportKind.ReadyNotReady, ReportsConstants.Categories.WorkforcePayroll);
        AddWorkforce("contact-center-agent-utilization", LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Agent utilization"), LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Busy plus wrap-up time divided by total observed signed-in time."), AgentWorkforceReportKind.Utilization, ReportsConstants.Categories.AgentPerformance);
        AddWorkforce("contact-center-agent-occupancy", LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Agent occupancy"), LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Busy plus wrap-up time divided by available, reserved, busy, and wrap-up time."), AgentWorkforceReportKind.Occupancy, ReportsConstants.Categories.AgentPerformance);
        AddWorkforce("contact-center-presence-reasons", LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Presence reason breakdown"), LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Observed presence duration and interval count by status and reason."), AgentWorkforceReportKind.ReasonBreakdown, ReportsConstants.Categories.WorkforcePayroll);
        AddWorkforce("contact-center-presence-audit", LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Agent presence audit"), LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Detailed auditable presence transitions with status, reason, and membership counts."), AgentWorkforceReportKind.PresenceAudit, ReportsConstants.Categories.ComplianceAudit);
        AddWorkforce("contact-center-queue-signed-in-hours", LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Queue signed-in hours"), LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Observed signed-in agent time attributed to queue memberships."), AgentWorkforceReportKind.QueueMembershipHours, ReportsConstants.Categories.WorkforcePayroll);
        AddWorkforce("contact-center-campaign-signed-in-hours", LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Campaign signed-in hours"), LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Observed signed-in agent time attributed to campaign memberships."), AgentWorkforceReportKind.CampaignMembershipHours, ReportsConstants.Categories.WorkforcePayroll);
        AddWorkforce("contact-center-payroll-timecard", LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Payroll timecard inputs"), LocalizationSource.Create<ConfigureContactCenterReportCatalog>("Observed on-duty, productive presence, break, meeting, training, and other not-ready time for payroll review; pay rates and schedules are not applied."), AgentWorkforceReportKind.PayrollTimecard, ReportsConstants.Categories.WorkforcePayroll);
    }
}
